-- Temucraft Collections window (like retail's): Mounts / Pet Journal / Toy Box / Heirlooms / Appearances / Campsites.
-- Mounts and Pet Journal: on the left a searchable list of every mount (pet) the game has, with a favourite star,
-- filters and "X / Y collected"; the ones this character doesn't have are greyed, with the item that teaches them.
-- On the right a 3D preview with the name, source and description, "Show Character", Mount (Summon) and "Summon
-- Random Favorite". The full list is TemucraftCollectionsData.lua (generated by client/collections/build_collections.py
-- from the server's DBCs and world DB); what the character has comes from GetCompanionInfo (mounts and pets are shared
-- across the account by mod-temucraft-account-wide). Favourites are kept per account (TemucraftStore).
-- Summoning uses CallCompanion, which the stock companion window uses too and isn't protected; list and layout
-- changes don't touch any secure frame.
-- Open it with /collections, or the Collections button of the spellbook.
local WIDTH, HEIGHT = 800, 560;
local ROWS, ROW_HEIGHT = 10, 42;
local RACES = { Human = 1, Orc = 2, Dwarf = 3, NightElf = 4, Scourge = 5, Tauren = 6, Gnome = 7, Troll = 8, Goblin = 9, BloodElf = 10, Draenei = 11 };
local CLASSES = { WARRIOR = 1, PALADIN = 2, HUNTER = 3, ROGUE = 4, PRIEST = 5, DEATHKNIGHT = 6, SHAMAN = 7, MAGE = 8, WARLOCK = 9, DRUID = 11 };

local function Has(mask, bit) return mask % (2 * bit) >= bit; end

----------------------------------------------------------------------------------------------------------------------
-- The logic (no frames: tests/collections_test.lua runs it with stubs)
----------------------------------------------------------------------------------------------------------------------
TemucraftCollectionsLogic = {};
local L = TemucraftCollectionsLogic;

-- may this race / class have it (masks 0 = everyone; unknown race or class = no filter)
function L.Allowed(raceMask, classMask, race, class)
	if ( raceMask > 0 and race and not Has(raceMask, 2 ^ (race - 1)) ) then return false; end
	if ( classMask > 0 and class and not Has(classMask, 2 ^ (class - 1)) ) then return false; end
	return true;
end

-- data rows { spell, creature, race, class, model, source }, owned[spell] = { index, name, icon, creature, active },
-- names(spell) -> name, icon; returns the entries (favourites, then collected, then the rest, by name) and the counts
function L.Build(data, owned, names, favourites, race, class)
	local list, seen = {}, {};
	local collected, total = 0, 0;
	for _, row in ipairs(data or {}) do
		local spell = row[1];
		local have = owned[spell];
		if ( not seen[spell] and (have or L.Allowed(row[3], row[4], race, class)) ) then
			local name, icon = names(spell);
			if ( have ) then name, icon = have.name or name, have.icon or icon; end
			if ( name ) then
				seen[spell] = true;
				local known = row[6] ~= "" or row[4] > 0;
				table.insert(list, { spell = spell, name = name, icon = icon, creature = (have and have.creature) or row[2], model = row[5],
					source = row[6], known = known or have ~= nil, owned = have ~= nil, index = have and have.index, active = have and have.active,
					favourite = favourites[spell] and true or false });
			end
		end
	end
	for spell, have in pairs(owned) do
		if ( not seen[spell] ) then
			seen[spell] = true;
			table.insert(list, { spell = spell, name = have.name, icon = have.icon, creature = have.creature, model = "", source = "",
				known = true, owned = true, index = have.index, active = have.active, favourite = favourites[spell] and true or false });
		end
	end
	for _, e in ipairs(list) do
		if ( e.owned ) then collected = collected + 1; end
		if ( e.known ) then total = total + 1; end
	end
	table.sort(list, function(a, b)
		if ( a.favourite ~= b.favourite ) then return a.favourite; end
		if ( a.owned ~= b.owned ) then return a.owned; end
		return a.name < b.name;
	end);
	return list, collected, total;
end

-- filters = { collected = bool, missing = bool, unknown = bool }
function L.Filter(list, query, filters)
	local out = {};
	query = string.lower(query or "");
	for _, e in ipairs(list) do
		local show = (e.owned and filters.collected) or (not e.owned and filters.missing and (e.known or filters.unknown));
		if ( show and query ~= "" ) then
			local text = string.lower(e.name.." "..(e.source or ""));
			for word in string.gmatch(query, "%S+") do
				if ( not string.find(text, word, 1, true) ) then show = false; break; end
			end
		end
		if ( show ) then table.insert(out, e); end
	end
	return out;
end

function L.ParseFavourites(text)
	local out = {};
	for id in string.gmatch(text or "", "%d+") do out[tonumber(id)] = true; end
	return out;
end
function L.SerializeFavourites(set)
	local ids = {};
	for id in pairs(set) do table.insert(ids, id); end
	table.sort(ids);
	return table.concat(ids, ",");
end

if ( not CreateFrame ) then return; end   -- tests load only the logic

