-- The window
----------------------------------------------------------------------------------------------------------------------
local frame = CreateFrame("Frame", "TemucraftCollectionsFrame", UIParent);
frame:SetWidth(WIDTH); frame:SetHeight(HEIGHT);
frame:SetPoint("CENTER", 0, 20);
frame:SetFrameStrata("HIGH"); frame:SetToplevel(true);
frame:EnableMouse(true); frame:SetMovable(true); frame:SetClampedToScreen(true);
frame:SetBackdrop({ bgFile = "Interface\\DialogFrame\\UI-DialogBox-Background-Dark", edgeFile = "Interface\\DialogFrame\\UI-DialogBox-Border",
	tile = true, tileSize = 32, edgeSize = 32, insets = { left = 11, right = 12, top = 12, bottom = 11 } });
frame:Hide();
tinsert(UISpecialFrames, "TemucraftCollectionsFrame");
local title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
title:SetPoint("TOP", 0, -20);
title:SetText("Collections");
CreateFrame("Button", "TemucraftCollectionsFrameCloseButton", frame, "UIPanelCloseButton"):SetPoint("TOPRIGHT", -6, -6);
frame:RegisterForDrag("LeftButton");
frame:SetScript("OnDragStart", function(self) self:StartMoving(); end);
frame:SetScript("OnDragStop", function(self) self:StopMovingOrSizing(); end);
frame:SetScript("OnShow", function() PlaySound("igCharacterInfoOpen"); end);
frame:SetScript("OnHide", function() PlaySound("igCharacterInfoClose"); end);

local panels = {};
local scan = CreateFrame("GameTooltip", "TemucraftCollectionsScanTooltip", nil, "GameTooltipTemplate");
local descriptions = {};
local function Description(spell)
	if ( descriptions[spell] == nil ) then
		scan:SetOwner(WorldFrame, "ANCHOR_NONE");
		scan:SetHyperlink("spell:"..spell);
		local text = "";
		for i = 2, scan:NumLines() do
			local left = _G["TemucraftCollectionsScanTooltipTextLeft"..i];
			local line = left and left:GetText();
			if ( line and #line > #text ) then text = line; end
		end
		scan:Hide();
		descriptions[spell] = text;
	end
	return descriptions[spell];
end

local function Favourites(kind) return L.ParseFavourites(TemucraftStore_Get and TemucraftStore_Get("A", "fav."..kind)); end

local function Journal(kind, noun)
	local panel = CreateFrame("Frame", "TemucraftCollections"..kind, frame);
	panel:SetPoint("TOPLEFT", 14, -40); panel:SetPoint("BOTTOMRIGHT", -14, 14);
	panel:Hide();
	local entries, shown, selected = {}, {}, nil;
	local filters = { collected = true, missing = true, unknown = false };
	local query = "";

	local count = panel:CreateFontString(nil, "OVERLAY", "GameFontNormal");
	count:SetPoint("TOPLEFT", 6, -2);
	local collectedText = panel:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	collectedText:SetPoint("TOPLEFT", count, "BOTTOMLEFT", 0, -4);

	local search = CreateFrame("EditBox", panel:GetName().."Search", panel, "InputBoxTemplate");
	search:SetWidth(180); search:SetHeight(20); search:SetAutoFocus(false);
	search:SetPoint("TOPLEFT", 12, -40);
	local hint = search:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall");
	hint:SetPoint("LEFT", 2, 0); hint:SetText(SEARCH or "Search");
	search:SetScript("OnEscapePressed", function(self) self:ClearFocus(); end);
	search:SetScript("OnEnterPressed", function(self) self:ClearFocus(); end);
	search:SetScript("OnEditFocusGained", function() hint:Hide(); end);
	search:SetScript("OnEditFocusLost", function(self) if ( self:GetText() == "" ) then hint:Show(); end end);

	local checks = {};
	local function Check(i, key, label)
		local c = CreateFrame("CheckButton", panel:GetName().."Filter"..i, panel, "UICheckButtonTemplate");
		c:SetWidth(20); c:SetHeight(20);
		c:SetPoint("TOPLEFT", 6 + (i - 1) * 100, -62);
		_G[c:GetName().."Text"]:SetText(label);
		_G[c:GetName().."Text"]:SetFontObject("GameFontHighlightSmall");
		c:SetChecked(filters[key]);
		c.key = key;
		checks[i] = c;
		return c;
	end
	Check(1, "collected", "Collected"); Check(2, "missing", "Not collected"); Check(3, "unknown", "Unknown source");

	local scroll = CreateFrame("ScrollFrame", panel:GetName().."Scroll", panel, "FauxScrollFrameTemplate");
	scroll:SetPoint("TOPLEFT", 0, -86); scroll:SetWidth(290); scroll:SetHeight(ROWS * ROW_HEIGHT);
	local rows = {};

	-- the preview
	local right = CreateFrame("Frame", nil, panel);
	right:SetPoint("TOPLEFT", 330, 0); right:SetPoint("BOTTOMRIGHT", 0, 0);
	right:SetBackdrop({ bgFile = "Interface\\Tooltips\\UI-Tooltip-Background", edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
		tile = true, tileSize = 16, edgeSize = 16, insets = { left = 4, right = 4, top = 4, bottom = 4 } });
	right:SetBackdropColor(0, 0, 0, 0.6);
	local model = CreateFrame("DressUpModel", panel:GetName().."Model", right);
	model:SetPoint("TOPLEFT", 6, -6); model:SetPoint("TOPRIGHT", -6, -6); model:SetHeight(300);
	local name = right:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
	name:SetPoint("TOPLEFT", model, "BOTTOMLEFT", 8, -8); name:SetWidth(400); name:SetJustifyH("LEFT");
	local source = right:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	source:SetPoint("TOPLEFT", name, "BOTTOMLEFT", 0, -6); source:SetWidth(400); source:SetJustifyH("LEFT");
	local desc = right:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	desc:SetPoint("TOPLEFT", source, "BOTTOMLEFT", 0, -8); desc:SetWidth(400); desc:SetJustifyH("LEFT");
	local showChar = CreateFrame("CheckButton", panel:GetName().."ShowCharacter", right, "UICheckButtonTemplate");
	showChar:SetWidth(22); showChar:SetHeight(22);
	showChar:SetPoint("TOPRIGHT", model, "TOPRIGHT", -110, -4);
	_G[showChar:GetName().."Text"]:SetText("Show Character");
	local summon = CreateFrame("Button", panel:GetName().."Summon", right, "UIPanelButtonTemplate");
	summon:SetWidth(130); summon:SetHeight(24);
	summon:SetPoint("BOTTOMRIGHT", -10, 10);
	local random = CreateFrame("Button", panel:GetName().."Random", right, "UIPanelButtonTemplate");
	random:SetWidth(200); random:SetHeight(24);
	random:SetPoint("BOTTOMLEFT", 10, 10);
	random:SetText(kind == "MOUNT" and "Summon Random Favorite Mount" or "Summon Random Favorite Pet");

	-- the model: the summoned creature if the client has it cached, else the model file
	local fallback, wait = nil, 0;
	model:SetScript("OnUpdate", function(self, elapsed)
		if ( not fallback ) then return; end
		wait = wait + elapsed;
		if ( wait < 0.1 ) then return; end
		local m = self.GetModel and self:GetModel();
		if ( type(m) ~= "string" or m == "" ) then self:SetModel(fallback); end
		fallback = nil;
	end);
	local turning, lastX = false, 0;
	model:EnableMouse(true);
	model:SetScript("OnMouseDown", function(self) turning, lastX = true, GetCursorPosition(); end);
	model:SetScript("OnMouseUp", function() turning = false; end);
	model:HookScript("OnUpdate", function(self)
		if ( not turning ) then return; end
		local x = GetCursorPosition();
		self:SetFacing((self:GetFacing() or 0) + (x - lastX) / 100);
		lastX = x;
	end);
	local function ShowModel(e)
		model:ClearModel();
		fallback = nil;
		if ( showChar:GetChecked() or not e ) then model:SetUnit("player"); return; end
		if ( e.creature and e.creature > 0 and model.SetCreature ) then
			model:SetCreature(e.creature);
			if ( e.model and e.model ~= "" ) then fallback, wait = e.model, 0; end
		elseif ( e.model and e.model ~= "" ) then
			model:SetModel(e.model);
		end
		model:SetFacing(0.5);
	end
	showChar:SetScript("OnClick", function() ShowModel(selected); end);

	local function Detail()
		local e = selected;
		if ( not e ) then
			name:SetText(""); source:SetText(""); desc:SetText("");
			summon:Disable(); summon:SetText(kind == "MOUNT" and "Mount" or "Summon");
			ShowModel(nil);
			return;
		end
		name:SetText(e.name);
		if ( e.owned ) then name:SetTextColor(NORMAL_FONT_COLOR.r, NORMAL_FONT_COLOR.g, NORMAL_FONT_COLOR.b);
		else name:SetTextColor(0.6, 0.6, 0.6); end
		source:SetText("|cffffd100Source:|r "..(e.source ~= "" and e.source or (e.owned and "Collected" or "Unknown")));
		desc:SetText(Description(e.spell));
		if ( e.owned ) then summon:Enable(); else summon:Disable(); end
		if ( e.active ) then summon:SetText(kind == "MOUNT" and "Dismount" or "Dismiss");
		else summon:SetText(kind == "MOUNT" and "Mount" or "Summon"); end
		ShowModel(e);
	end

	local function Refresh()
		local owned = {};
		for i = 1, GetNumCompanions(kind) do
			local creature, cname, spell, icon, active = GetCompanionInfo(kind, i);
			if ( spell ) then owned[spell] = { index = i, name = cname, icon = icon, creature = creature, active = active and true or false }; end
		end
		local _, raceToken = UnitRace("player");
		local _, classToken = UnitClass("player");
		local data = TEMUCRAFT_COLLECTIONS and TEMUCRAFT_COLLECTIONS[kind];
		local collected, total;
		entries, collected, total = L.Build(data, owned, function(id) local n, _, icon = GetSpellInfo(id); return n, icon; end,
			Favourites(kind), RACES[raceToken], CLASSES[classToken]);
		shown = L.Filter(entries, query, filters);
		count:SetText(format("Total %s: |cffffffff%d|r", noun, collected));
		collectedText:SetText(format("%d / %d collected", collected, total));
		if ( selected ) then
			local keep = nil;
			for _, e in ipairs(entries) do if ( e.spell == selected.spell ) then keep = e; end end
			selected = keep;
		end
		if ( not selected ) then selected = shown[1]; end
		FauxScrollFrame_Update(scroll, #shown, ROWS, ROW_HEIGHT);
		local offset = FauxScrollFrame_GetOffset(scroll);
		for i, row in ipairs(rows) do
			local e = shown[offset + i];
			row.entry = e;
			if ( e ) then
				row.icon:SetTexture(e.icon);
				row.icon:SetDesaturated(not e.owned);
				row.name:SetText(e.name);
				if ( e.owned ) then row.name:SetTextColor(1, 1, 1); else row.name:SetTextColor(0.5, 0.5, 0.5); end
				row.sub:SetText(e.owned and (e.active and "|cff40ff40Summoned|r" or "") or (e.source ~= "" and e.source or "Unknown source"));
				row.star:SetAlpha(e.favourite and 1 or 0);
				if ( selected and selected.spell == e.spell ) then row:LockHighlight(); else row:UnlockHighlight(); end
				row:Show();
			else
				row:Hide();
			end
		end
		Detail();
	end
	panel.Refresh = Refresh;

	local function ToggleFavourite(e)
		local set = Favourites(kind);
		set[e.spell] = (not set[e.spell]) or nil;
		if ( TemucraftStore_Set ) then TemucraftStore_Set("A", "fav."..kind, L.SerializeFavourites(set)); end
		Refresh();
	end

	for i = 1, ROWS do
		local row = CreateFrame("Button", panel:GetName().."Row"..i, panel);
		row:SetWidth(286); row:SetHeight(ROW_HEIGHT - 2);
		row:SetPoint("TOPLEFT", scroll, "TOPLEFT", 4, -(i - 1) * ROW_HEIGHT);
		row:RegisterForClicks("LeftButtonUp", "RightButtonUp");
		row:RegisterForDrag("LeftButton");
		row:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD");
		row.icon = row:CreateTexture(nil, "ARTWORK");
		row.icon:SetWidth(34); row.icon:SetHeight(34); row.icon:SetPoint("LEFT", 2, 0);
		row.name = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight");
		row.name:SetPoint("TOPLEFT", row.icon, "TOPRIGHT", 8, -3); row.name:SetWidth(210); row.name:SetJustifyH("LEFT");
		row.sub = row:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall");
		row.sub:SetPoint("TOPLEFT", row.name, "BOTTOMLEFT", 0, -3); row.sub:SetWidth(210); row.sub:SetJustifyH("LEFT");
		row.star = row:CreateTexture(nil, "OVERLAY");
		row.star:SetTexture("Interface\\TargetingFrame\\UI-RaidTargetingIcon_1");
		row.star:SetWidth(16); row.star:SetHeight(16); row.star:SetPoint("TOPLEFT", row.icon, "TOPLEFT", -4, 4);
		row:SetScript("OnClick", function(self, button)
			if ( not self.entry ) then return; end
			if ( button == "RightButton" ) then ToggleFavourite(self.entry); return; end
			if ( IsModifiedClick("CHATLINK") ) then
				local link = GetSpellLink(self.entry.spell);
				if ( link ) then ChatEdit_InsertLink(link); end
				return;
			end
			selected = self.entry;
			Refresh();
		end);
		row:SetScript("OnDoubleClick", function(self)
			if ( self.entry and self.entry.owned ) then CallCompanion(kind, self.entry.index); end
		end);
		row:SetScript("OnDragStart", function(self)
			if ( self.entry and self.entry.owned ) then PickupCompanion(kind, self.entry.index); end
		end);
		row:SetScript("OnEnter", function(self)
			if ( not self.entry ) then return; end
			GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
			GameTooltip:SetHyperlink("spell:"..self.entry.spell);
			GameTooltip:AddLine(self.entry.favourite and "Right click: remove from favourites" or "Right click: add to favourites", 0.6, 0.6, 0.6);
			GameTooltip:Show();
		end);
		row:SetScript("OnLeave", function() GameTooltip:Hide(); end);
		rows[i] = row;
	end
	scroll:SetScript("OnVerticalScroll", function(self, offset) FauxScrollFrame_OnVerticalScroll(self, offset, ROW_HEIGHT, Refresh); end);
	search:SetScript("OnTextChanged", function(self)
		if ( self:GetText() ~= "" ) then hint:Hide(); end
		query = self:GetText();
		FauxScrollFrame_SetOffset(scroll, 0);
		Refresh();
	end);
	for _, c in ipairs(checks) do
		c:SetScript("OnClick", function(self) filters[self.key] = self:GetChecked() and true or false; Refresh(); end);
	end

	summon:SetScript("OnClick", function()
		local e = selected;
		if ( not e or not e.owned ) then return; end
		if ( e.active ) then
			if ( kind == "MOUNT" ) then Dismount(); else DismissCompanion(kind); end
		else
			CallCompanion(kind, e.index);
		end
	end);
	random:SetScript("OnClick", function()
		local pool, all = {}, {};
		for _, e in ipairs(entries) do
			if ( e.owned ) then
				table.insert(all, e);
				if ( e.favourite ) then table.insert(pool, e); end
			end
		end
		if ( #pool == 0 ) then pool = all; end
		if ( #pool == 0 ) then return; end
		CallCompanion(kind, pool[math.random(#pool)].index);
	end);
	panel:SetScript("OnShow", Refresh);
	return panel;
end

local function Placeholder(key, text)
	local panel = CreateFrame("Frame", "TemucraftCollections"..key, frame);
	panel:SetPoint("TOPLEFT", 14, -40); panel:SetPoint("BOTTOMRIGHT", -14, 14);
	panel:Hide();
	local line = panel:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
	line:SetPoint("CENTER", 0, 20); line:SetText("Coming later.");
	local more = panel:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	more:SetPoint("TOP", line, "BOTTOM", 0, -10); more:SetWidth(500); more:SetText(text);
	return panel;
end

panels[1] = Journal("MOUNT", "Mounts");
panels[2] = Journal("CRITTER", "Pets");
panels[3] = Placeholder("Toys", "Toys and illusions (mod-temucraft-lostlands, mod-temucraft-account-wide) will be listed here.");
panels[4] = Placeholder("Heirlooms", "Heirlooms will be listed here.");
panels[5] = Placeholder("Appearances", "Transmog appearances you have unlocked (mod-transmog) will be listed here.");
panels[6] = Placeholder("Campsites", "Campsites (mod-temucraft-camping) will be listed here.");
local TAB_NAMES = { "Mounts", "Pet Journal", "Toy Box", "Heirlooms", "Appearances", "Campsites" };
local current = 1;
local tabs = {};
local function Select(index)
	current = index;
	for i, p in ipairs(panels) do if ( i == index ) then p:Show(); else p:Hide(); end end
	PanelTemplates_SetTab(frame, index);
end
for i, label in ipairs(TAB_NAMES) do
	local tab = CreateFrame("Button", "TemucraftCollectionsFrameTab"..i, frame, "CharacterFrameTabButtonTemplate");
	tab:SetID(i); tab:SetText(label);
	if ( i == 1 ) then tab:SetPoint("TOPLEFT", frame, "BOTTOMLEFT", 20, 8); else tab:SetPoint("LEFT", tabs[i - 1], "RIGHT", -16, 0); end
	tab:SetScript("OnClick", function(self) PlaySound("igCharacterInfoTab"); Select(self:GetID()); end);
	tabs[i] = tab;
end
PanelTemplates_SetNumTabs(frame, #TAB_NAMES);

function TemucraftCollections_Toggle(index)
	if ( frame:IsShown() and (not index or index == current) ) then frame:Hide(); return; end
	frame:Show();
	Select(index or current);
end

SLASH_TEMUCRAFTCOLLECTIONS1 = "/collections";
SLASH_TEMUCRAFTCOLLECTIONS2 = "/tcol";
SlashCmdList["TEMUCRAFTCOLLECTIONS"] = function(msg)
	msg = strlower(strtrim(msg or ""));
	TemucraftCollections_Toggle((msg == "pets" or msg == "pet") and 2 or 1);
end;

local events = CreateFrame("Frame");
events:RegisterEvent("COMPANION_LEARNED");
events:RegisterEvent("COMPANION_UPDATE");
events:RegisterEvent("PLAYER_ENTERING_WORLD");
events:SetScript("OnEvent", function()
	if ( frame:IsShown() and panels[current].Refresh ) then panels[current].Refresh(); end
end);
if ( TemucraftStore_OnReady ) then
	TemucraftStore_OnReady(function() if ( frame:IsShown() and panels[current].Refresh ) then panels[current].Refresh(); end end);
end
